import{_ as l,l as o,o as e,c as s,v as t,p as n,x as r,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"负载均衡与迁移","description":"","frontmatter":{"title":"负载均衡与迁移","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/load-balance-migrate.md","filePath":"cs/load-balance-migrate.md","lastUpdated":1789023840000}'),p={name:"cs/load-balance-migrate.md"};function m(_,a,u,f,B,E){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="负载均衡与迁移" tabindex="-1">负载均衡与迁移 <a class="header-anchor" href="#负载均衡与迁移" aria-label="Permalink to &quot;负载均衡与迁移&quot;">​</a></h1><div class="epigraph"><p>每 CPU 一条运行队列之后，必须有人把过重的核上的任务搬到过轻的核上；搬迁付缓存与 TLB 的税。</p><footer>—— 据 Love, Linux Kernel Development；Silberschatz et al. 对多处理器调度的整理</footer></div><p><a href="/cs/nice-weight">上一课</a>让单队列里的权重有意义。多核上<a href="/cs/runqueue">运行队列</a>是 per-CPU 的：若所有可运行任务挤在 CPU0，其余核跑 idle，份额再精致也没用。缺口是<strong>负载均衡</strong>：比较各队列负载（可运行权重和），把任务迁移到别的核。本课钉何时搬、搬的代价，不写 NUMA 距离表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>唤醒时入哪条队列：上一唤醒者所在核（缓存热）还是当前最闲核（立刻有 CPU）？周期性平衡：偷或推任务。迁移必须改 PCB 的 CPU 字段、从旧队列摘下、在新队列按 vruntime 调整——两核之间的 min_vruntime 不同，要折算，否则刚迁入的人会饿死或垄断。缺口不是 nice 表，而是<strong>跨队列的一致性</strong>。</p><p><span class="marginnote">亲和掩码可以禁止迁到某些核。硬亲和下一课才展开；本课承认掩码是迁移的约束。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>触发：新任务、任务唤醒、核变 idle、定时 tick。比较负载；若不平衡超过阈值，选一个可迁任务（最好缓存冷、不在运行）。IPI 踢目标核重新调度。idle 平衡更积极：与其空转，不如付一次迁移税。</p>',8)),(e(),n(h,null,{default:r(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E9%87%8D%E9%98%9F%E5%88%97%22%5D%20--%3E%20MIG%5B%22%E8%BF%81%E7%A7%BB%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20MIG%20--%3E%20L%5B%22%E8%BD%BB%E9%98%9F%E5%88%97%22%5D%0A%20%20MIG%20--%3E%20TAX%5B%22%E7%BC%93%E5%AD%98%E4%B8%8E%20TLB%20%E5%8F%98%E5%86%B7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/context-switch">上下文切换</a> 的差别：切换可在同核；迁移是换核，页表根若同进程可不换，但 cache 几乎必冷。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>平衡让 vruntime 公平从单核近似变成全机近似：长期看，任务在各核上分到的时间还受「当时在哪条队列」影响。迁得太勤，吞吐掉进 cache miss；迁得太懒，有核 idle。这是<a href="/cs/scheduling-metrics">调度指标</a>里利用率与吞吐的多核版，不是新尺子。</p><p>实时任务通常不参与公平偷任务，或单独规则，以免期限被搬到忙核。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把调度域拓扑（SMT / 核 / 包）的全部层次写成手册，不讨论工作窃取的每一种启发式。NUMA 上「闲但远端」可能比「稍忙但本地」更差，那是再后一课。硬件中断亲和已经讲过，与任务迁移是一对。</p><p>后课默认：分时多核靠迁移摊负载。期限任务不能靠摊份额，下一课<a href="/cs/realtime-sched">实时调度对照</a>已经换尺子，其后展开 RM。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>per-CPU 队列必须迁移，否则有核闲、有核挤。</li><li>迁移折算 vruntime，并付缓存税。</li><li>实时对照与 RM 是下一课序。</li><li>出处：Love, <em>LKD</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',9))])}const b=l(p,[["render",m]]);export{T as __pageData,b as default};
